qss_template.button_primary:
QPushButton {{ background-color: {accent}; color: {text_inverse}; border: none; border-radius: {radius_md}px; padding: 6px 20px; font-weight: {weight_medium}; }}
QPushButton:hover {{ background-color: {accent_hover}; }}
QPushButton:pressed {{ background-color: {accent_pressed}; }}
QPushButton:disabled {{ background-color: {accent_disabled}; }}

qss_template.checkbox:
QCheckBox {{ spacing: 8px; }}
QCheckBox::indicator:checked {{ background-color: {accent}; border-radius: 3px; }}
QCheckBox::indicator:unchecked {{ border: 1px solid {border_default}; border-radius: 3px; }}

qss_template.combo:
QComboBox {{ background-color: {bg_input}; border: 1px solid {border_default}; border-radius: {radius_md}px; padding: 4px 10px; color: {text_primary}; }}
QComboBox:focus {{ border-color: {accent}; }}
QComboBox::drop-down {{ border: none; }}
QComboBox QAbstractItemView {{ background-color: {bg_card}; border: 1px solid {border_default}; selection-background-color: {accent}; }}

qss_template.input:
QLineEdit {{ background-color: {bg_input}; border: 1px solid {border_default}; border-radius: {radius_md}px; padding: 6px 12px; color: {text_primary}; }}
QLineEdit:focus {{ border-color: {accent}; }}
QLineEdit:disabled {{ opacity: {opacity_disabled}; }}

qss_template.list:
QListWidget {{ background-color: {bg_input}; border: 1px solid {border_default}; border-radius: {radius_md}px; outline: none; }}
QListWidget::item {{ padding: 6px 12px; }}
QListWidget::item:selected {{ background-color: {accent}; color: {text_inverse}; }}
QListWidget::item:hover {{ background-color: {bg_card_hover}; }}

qss_template.scrollbar:
QScrollBar:vertical {{ background-color: transparent; width: 8px; margin: 0; }}
QScrollBar::handle:vertical {{ background-color: {border_default}; border-radius: 4px; min-height: 30px; }}
QScrollBar::handle:vertical:hover {{ background-color: {border_hover}; }}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {{ height: 0; }}

qss_template.tab:
QTabWidget::pane {{ border: none; background-color: transparent; }}
QTabBar::tab {{ background-color: transparent; color: {text_muted}; padding: 8px 16px; border-bottom: 2px solid transparent; }}
QTabBar::tab:selected {{ color: {text_primary}; border-bottom: 2px solid {accent}; }}
QTabBar::tab:hover {{ color: {text_secondary}; }}
